  "common.footer.work.dariela": "Платформа для производителя продуктов",
  "common.footer.work.impos": "Сайт, который сначала завоёвывает доверие",
  "common.footer.work.interior": "Магазин на 80 000 товаров",
  "common.nav.about": "Обо мне",
